scwin.trigger2_onclick = function(e) {};
scwin.simulateWrapper = function(target, type, options) {
    WebSquare.wUnit.getJq(target).simulate(type, options);
}
scwin.setSimulate1 = function() {
    scwin.simulateWrapper('#grid1_column3', 'drag-n-drop', {
        dx: -10,
        dy: -50
    });
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    //Test step 1. 샘플실행 후 '조회'버튼 클릭 후 '분류2'항목을 'A'값으로 필터링한다.
    //1. After executing the sample, click the 'Query' button and filter the 'Classification 2' item to 'A' value.
    //Verify step 1. The 'Category 2' field is filtered by the 'A' value.
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('grid1_column3_filter').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('.w2grid_customFilter_list_listColumn_checkbox')[1].click()");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('.w2grid_customFilter_list_listColumn_checkbox')[2].click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_0_0').text() == '0'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_0_1').text() == 'A'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_1_1').text() == 'A'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_2_1').text() == 'A'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_0_2').text() == '1'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_1_2').text() == '2'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_2_2').text() == '3'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 2. '분류2'항목을 groupby 시킨다.
    //2. Group the item 'Category 2'.
    //Verify step 2. The 'Category 2' item is grouped.
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('.w2grid_groupbyZone_column').length == 1", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_0_0').text() == 'header1'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_0_1').text() == 'header2'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_0_2').text() == 'header3'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_4_0').text() == 'footer1'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_4_1').text() == 'footer2'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_4_2').text() == 'footer3'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_5_0').text() == 'header1'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_5_1').text() == 'header2'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_5_2').text() == 'header3'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_10_0').text() == 'footer1'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_10_1').text() == 'footer2'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_10_2').text() == 'footer3'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //formatter
    window.testFunc = function(data, fdata, row, col) {
        if (fdata == "A") {
            grid1.setRowColor(row, "blue");
        }
        return data;
    };
    //Function 
    //Created by: Thuyet.Pham
    //Created date: 30-Mar-2018
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
